315	func convertMemoPropertyFromStore(property *storepb.MemoPayload_Property) *v1pb.Memo_Property {
316		if property == nil {
317			return nil
318		}
319		return &v1pb.Memo_Property{
320			HasLink:            property.HasLink,
321			HasTaskList:        property.HasTaskList,
322			HasCode:            property.HasCode,
323			HasIncompleteTasks: property.HasIncompleteTasks,
324			Title:              property.Title,
325		}
326	}
